// Turn the request into script input. Two kinds of source:
//  1. a link (our own breakpointsystems.com page, or an outside article that gets credited), or
//  2. a written topic brief from Billy (his own notes, treated as approved).
// Never throws: an unreadable link is reported to Slack instead.
const S = $('Show Settings').first().json;
const req = $('Episode Request').first().json;
const url = String(req.source_url || '').trim();
const brief = String(req.brief || '').trim();
let html = '';
try { if ($('Get Source Page').isExecuted) { const p = $('Get Source Page').first().json || {}; html = String(p.data || p.body || ''); } } catch (e) {}
const hm = url.match(/^https?:\/\/([^\/?#:\s]+)/i);
const host = hm ? hm[1].toLowerCase().replace(/^www\./, '') : '';
const ownDomains = String(S.own_domains || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const isOwnLink = !!host && ownDomains.some(d => host === d || host.endsWith('.' + d));
const kind = !url && brief ? 'brief' : isOwnLink ? 'own' : 'article';
const site = kind === 'article' ? (host || 'the source website') : S.brand_name;

const tm = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
let title = tm ? tm[1].replace(/<[^>]+>/g, '').replace(/&amp;/gi, '&').replace(/&#39;|&rsquo;/gi, "'").replace(/\s*[|][^|]*$/, '').trim() : '';
if (!title && kind === 'brief') title = brief.split(/\r?\n/)[0].replace(/^[#*\-\s]+/, '').slice(0, 120).trim();
if (!title && url) { const last = (url.split('?')[0].split('/').filter(Boolean).pop() || '').replace(/-/g, ' ').trim(); title = last.replace(/\b\w/g, c => c.toUpperCase()); }
if (!title) title = 'Automation for Business Owners';

let body = '';
if (kind === 'brief') body = brief.replace(/\s+/g, ' ').trim().substring(0, 20000);
else {
  let main = html;
  const art = html.match(/<article[\s\S]*?<\/article>/i) || html.match(/<main[\s\S]*?<\/main>/i);
  if (art && art[0].length > 1500) main = art[0];
  body = main.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<nav[\s\S]*?<\/nav>/gi, ' ').replace(/<footer[\s\S]*?<\/footer>/gi, ' ').replace(/<aside[\s\S]*?<\/aside>/gi, ' ')
    .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/gi, ' ').replace(/&amp;/gi, '&').replace(/&#?[a-z0-9]+;/gi, ' ')
    .replace(/\s+/g, ' ').trim().substring(0, 20000);
}
// A brief can be short (Billy's notes); a web page needs real content.
const readable = kind === 'brief' ? body.length >= 200 : body.length >= 1200;

const factRule = kind === 'article'
  ? "- The source is an OUTSIDE article from " + site + ". It was not written by " + S.brand_name + ". Use ONLY facts stated in it and add no facts, numbers or statistics that are not in it.\n- Credit it out loud at least once, by name: for example the co-host says \"According to " + site + ", ...\".\n- Explain it in Billy's own words. Never read or copy long passages word for word.\n- Do not present the article's opinions as Billy's advice."
  : "- The source is " + (kind === 'brief' ? "Billy's own topic brief" : "a page from the " + S.brand_name + " website") + ". Billy has approved it. Use its facts, numbers and examples exactly as written. Never hedge them.\n- Do NOT add facts, statistics, percentages, dollar figures, tool prices, client names or results that are not in the source. If the source has no numbers, the script has no numbers.\n- You MAY add general, widely known explanations of how common business tools work (for example what a CRM or an automated follow-up does), as long as they contain no numbers, prices or claims about specific companies.";
const editorFactRule = kind === 'article'
  ? "1. Facts: the SOURCE is an outside article from " + site + ". Every fact, number and statistic in the script must appear in it; remove any the writer added. It must be credited by name at least once. Replace any long passage copied word for word with plain words."
  : "1. Facts: the SOURCE is approved " + (kind === 'brief' ? "(Billy's own brief)" : "(our own website)") + ". Never remove, soften or hedge what it says. REMOVE any statistic, percentage, dollar figure, tool price, client name, testimonial or result that appears nowhere in the source: the writer may not invent them.";
const words = { min: Number(S.episode_word_min) || 850, max: Number(S.episode_word_max) || 1050 };
return [{ json: {
  show_name: S.show_name, brand_name: S.brand_name, host_name: S.host_name, cohost_name: S.cohost_name,
  listener: S.listener, cta_line: S.cta_line, spoken_ai_line: S.spoken_ai_line || '',
  word_min: words.min, word_max: words.max,
  topic: title,
  source_url: url,
  source_type: kind,
  site: site,
  readable: readable,
  fact_rule: factRule,
  editor_fact_rule: editorFactRule,
  compiled_content: (kind === 'brief' ? "BILLY'S TOPIC BRIEF: " : kind === 'own' ? 'OUR PAGE: ' : 'ARTICLE: ') + title + (url ? '. SOURCE: ' + url + (kind === 'article' ? ' (' + site + ')' : '') : '') + '. BODY: ' + body
} }];

// Read the editor's JSON. If it is unreadable, keep the writer's script and say so.
// Then repair formatting so a stray line never sinks an episode: lines without a speaker join the line before.
const CO = $('Build Script Input').first().json.cohost_name;
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const NAMES = '(' + esc(CO) + '|Billy)';
const raw = String($input.first().json.text || '').trim();
const txt = raw.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let parsed = null;
try { parsed = JSON.parse(txt); } catch (e) {
  const m = txt.match(/\{[\s\S]*\}/);
  if (m) { try { parsed = JSON.parse(m[0]); } catch (e2) {} }
}
const original = String($('Write Dialogue').first().json.text || '');
const ok = parsed && typeof parsed.script === 'string' && parsed.script.trim().length > 3000;
function repair(s) {
  const out = [];
  // A speaker label in the middle of a line would be read aloud, so it starts a new line
  const split = String(s).replace(new RegExp('([.!?…"”)\\]:;,—–-])[ \\t]+(?:\\*\\*)?' + NAMES + '(?:\\*\\*)?\\s*:\\s*', 'gi'), '$1\n$2: ');
  for (const rawLine of split.split(/\r?\n/)) {
    let l = rawLine.replace(/\*\*/g, '').replace(/^\s*(?:[-*•]|#+)\s+/, '').trim();
    if (!l) continue;
    l = l.replace(new RegExp('^' + NAMES + '(?:\\s+jordan)?(?:\\s*\\([^)]*\\))?\\s*:\\s*', 'i'), (m, w) => (w.toLowerCase() === 'billy' ? 'Billy' : CO) + ': ');
    if (new RegExp('^' + NAMES + ': ').test(l)) out.push(l);
    else if (out.length) out[out.length - 1] += ' ' + l;
    else out.push(CO + ': ' + l);
  }
  return out.join('\n');
}
const chosen = ok ? parsed.script.trim() : original;
const fixed = repair(chosen);
const issues = ok && Array.isArray(parsed.issues) ? parsed.issues.slice(0, 12) : ['Editor output unreadable, so the writer script was kept as is.'];
if (fixed !== chosen.split(/\r?\n/).map(x => x.trim()).filter(Boolean).join('\n')) issues.push('Formatting repaired automatically (lines without a speaker were joined to the line before; a speaker name in the middle of a line was moved to its own line).');
return [{ json: { text: fixed, editor_issues: issues } }];

// Summarize the ledger for the duplicate check (questions already answered or in progress)
const rows = $input.all().map(i => i.json).filter(r => r && r.question);
const live = rows.filter(r => ['published', 'scheduled'].includes(r.status));
const list = live.map(r => '#' + (r.episode_number || '?') + ' [' + (r.topic || '') + '] ' + r.question).join('\n');
return [{ json: { ledger_questions: list || '(none yet)', ledger_count: live.length } }];

// Read the episode details JSON from the AI and check it
const raw = String($input.first().json.text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
let d = null;
try { d = JSON.parse(raw); } catch (e) { const m = raw.match(/\{[\s\S]*\}/); if (m) d = JSON.parse(m[0]); }
if (!d) throw new Error('Episode details were not valid JSON');
const TOPICS = ['Lead Follow-Up', 'AI Receptionists', 'CRM', 'Workflow Automation', 'AI Search', 'Operations', 'Case Study'];
const topic = TOPICS.find(t => t.toLowerCase() === String(d.topic || '').toLowerCase()) || 'Operations';
const slugify = s => String(s || '').toLowerCase().replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80).replace(/-+$/, '');
const gate = $('Script Gate').first().json;
const fix = s => String(s || '').replace(/\bBreak\s+Point\b/gi, 'Breakpoint').trim();
const out = {
  title: fix(d.title).slice(0, 110),
  slug: slugify(d.slug || d.title),
  question: String(d.question || '').trim(),
  topic: topic,
  quick_answer: fix(d.quick_answer).slice(0, 240),
  summary: fix(d.summary).slice(0, 300),
  seo_title: fix(d.seo_title).slice(0, 62),
  meta_description: fix(d.meta_description).slice(0, 160),
  bullets: Array.isArray(d.bullets) ? d.bullets.slice(0, 4).map(fix) : [],
  duplicate_of: (d.duplicate_of === null || d.duplicate_of === undefined || d.duplicate_of === '' || d.duplicate_of === false) ? null : d.duplicate_of,
  final_script: gate.final_script,
  word_count: gate.word_count,
  est_minutes: gate.est_minutes,
  script_chars: gate.script_chars,
  editor_issues: gate.editor_issues,
  source_url: $('Build Script Input').first().json.source_url
};
if (!out.title || !out.slug || !out.question) throw new Error('Episode details missing title, slug or question');
out.is_duplicate = out.duplicate_of !== null;
return [{ json: out }];

// Approved, declined, or no answer in time? Weekends publish on no answer (Billy, Oct 12).
const r = $input.first().json || {};
const a = r.data ? r.data.approved : undefined;
const etDay = $now.setZone('America/New_York').weekday; // 6 = Sat, 7 = Sun
const weekend = etDay === 6 || etDay === 7;
const approved = a === true;
const declined = a === false;
const noAnswer = !approved && !declined;
return [{ json: { go: approved || (noAnswer && weekend), approved, declined, no_answer: noAnswer, weekend,
  decision: approved ? 'approved' : declined ? 'declined' : (weekend ? 'weekend_auto_approved' : 'expired') } }];

// ---- Breakpoint release rule ----
// One episode per release day (Show Settings: release_days, release_time, Eastern time).
// No date asked: the next release day with no episode. Date asked: that day if it is free and not passed
// (any weekday is allowed on purpose), otherwise the next free release day after it.
// "after:YYYY-MM-DD" (extra links in a dated batch): the first free release day on or after that date.
const S = $('Show Settings').first().json;
const SHOW_ID = String(S.transistor_show_id || '').trim();
const NY = 'America/New_York';
const DAY = { mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6, sun: 7 };
const days = String(S.release_days || 'Tue').split(/[\s,]+/).map(d => DAY[d.trim().slice(0, 3).toLowerCase()]).filter(Boolean);
const releaseDays = days.length ? days : [2];
const tm = String(S.release_time || '09:00').match(/^(\d{1,2}):(\d{2})$/);
const HM = tm ? [Math.min(23, +tm[1]), Math.min(59, +tm[2])] : [9, 0];
function pickSlot(rows, airDateRaw, now) {
  const taken = new Set();
  for (const r of rows) {
    if (!r || !['published', 'scheduled'].includes(r.status)) continue;
    const t = r.release_at || r.published_at;
    if (!t) continue;
    const dt = DateTime.fromISO(typeof t === 'string' ? t : new Date(t).toISOString(), { zone: NY });
    if (dt.isValid) taken.add(dt.toFormat('yyyy-LL-dd'));
  }
  const at = d => d.setZone(NY).set({ hour: HM[0], minute: HM[1], second: 0, millisecond: 0 });
  const soon = now.plus({ minutes: 30 });
  const free = d => !taken.has(d.toFormat('yyyy-LL-dd')) && at(d) > soon;
  const nextRelease = from => { let d = at(from); for (let i = 0; i < 730; i++, d = d.plus({ days: 1 })) if (releaseDays.includes(d.weekday) && free(d)) return at(d); return at(from.plus({ days: 1 })); };
  const raw = String(airDateRaw || '').trim();
  const after = /^after:/i.test(raw);
  const ds = raw.replace(/^after:/i, '');
  let slot = null, note = '';
  if (/^\d{4}-\d{2}-\d{2}$/.test(ds)) {
    const day = DateTime.fromISO(ds, { zone: NY });
    if (!day.isValid) note = 'The date asked for could not be read, so this takes the next release day.';
    else if (after) slot = nextRelease(day < now ? now : day);
    else if (free(day)) { slot = at(day); note = 'Airs on the date you asked for.'; }
    else { slot = nextRelease(day < now ? now : day.plus({ days: 1 })); note = day.toFormat('LLL d') + ' is taken or has passed, so this airs on the next release day.'; }
  } else if (raw) note = 'The date asked for could not be read, so this takes the next release day.';
  if (!slot) slot = nextRelease(now);
  return {
    release_at_iso: slot.toISO(),
    release_at_utc: slot.toUTC().toISO(),
    release_label: slot.toFormat("cccc, LLL d 'at' h:mm a") + ' ET',
    publish_date_cms: slot.toFormat('yyyy-LL-dd') + 'T16:00:00.000Z',
    air_note: note
  };
}

// Stop before any voice credits are spent if the Breakpoint show doesn't exist in Transistor yet.
if (!SHOW_ID) throw new Error('Breakpoint podcast: no Transistor show ID yet. Create the show in Transistor and paste its ID into transistor_show_id in the Show Settings node. Nothing was spent on voices.');
const d = $('Read Episode Details').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && (!r.show_id || String(r.show_id) === SHOW_ID));
// The lowest episode number not in use, so a pulled and remade episode keeps its number
const used = new Set(rows.filter(r => ['published', 'scheduled'].includes(r.status)).map(r => Number(r.episode_number) || 0));
let n = 0; while (used.has(n + 1)) n++;
const s = pickSlot(rows, $('Episode Request').first().json.air_date, DateTime.now().setZone(NY));
return [{ json: { episode_number: n + 1, ...s, ...d, show_id: SHOW_ID, show_name: S.show_name } }];

// Split the co-host + Billy dialogue into ElevenLabs Text to Dialogue chunks.
// Chunk 0 is ONLY the co-host's hook line, so the intro music (if any) goes right after it.
const S = $('Show Settings').first().json;
const script = $('Plan Release').first().json.final_script || '';
const CO = S.cohost_name;
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const VOICES = { [CO.toLowerCase()]: S.cohost_voice, billy: S.host_voice };
const MAX_CHARS = 1500;
const turns = [];
let cur = null;
const names = '(' + esc(CO) + '|Billy)';
for (const raw of script.replace(new RegExp('([.!?…"”)\\]:;,—–-])[ \\t]+' + names + '\\s*:\\s*', 'gi'), '$1\n$2: ').split(/\r?\n/)) {
  const line = raw.trim();
  if (!line) continue;
  const m = line.match(new RegExp('^' + names + '\\s*:\\s*(.*)$', 'i'));
  if (m) { if (cur) turns.push(cur); cur = { voice_id: VOICES[m[1].toLowerCase()], text: m[2].trim() }; }
  else if (cur) { cur.text += ' ' + line; }
}
if (cur) turns.push(cur);
const clean = turns.filter(t => t.voice_id && t.text);
if (clean.length < 2) throw new Error('Split Dialogue: no co-host/Billy turns parsed');
const chunks = [[clean[0]]];
let chunk = [], len = 0;
for (const t of clean.slice(1)) {
  const add = t.text.length + 12;
  if (len + add > MAX_CHARS && chunk.length) { chunks.push(chunk); chunk = []; len = 0; }
  chunk.push({ text: t.text, voice_id: t.voice_id });
  len += add;
}
if (chunk.length) chunks.push(chunk);
return chunks.map((inputs, i) => ({ json: { dialogue_inputs: inputs, chunk_index: i, is_hook: i === 0, total_chunks: chunks.length } }));

// Audio parts fetched from GitHub (AutomateTJIA/smart-coverage-podcast, branch main).
// The 0.6 s silence is shared and unbranded. Music is used only when Show Settings use_music = 'yes'
// and Breakpoint's own intro/outro files exist (none yet; the insurance show's music is NOT reused).
const S = $('Show Settings').first().json;
const out = [{ json: { part: 'gap', path: 'assets/audio/factory/the-jordan-insurance-agency-factory-gap-0.6s.mp3' } }];
if (String(S.use_music).toLowerCase() === 'yes' && S.music_intro_path && S.music_outro_path) {
  out.push({ json: { part: 'intro', path: S.music_intro_path } });
  out.push({ json: { part: 'outro', path: S.music_outro_path } });
}
return out;

// Join: hook -> gap -> [intro music] -> rest of the dialogue -> [gap -> sign-off music].
// Without Breakpoint music (Show Settings use_music) it is: hook -> gap -> rest of the dialogue.
// All parts are 44.1 kHz mono 128 kbps MP3, so frames can be joined directly once tags are stripped.
function cleanMp3(buf) {
  let start = 0, end = buf.length;
  if (buf.length > 10 && buf[0] === 0x49 && buf[1] === 0x44 && buf[2] === 0x33) {
    const size = (buf[6] & 0x7f) << 21 | (buf[7] & 0x7f) << 14 | (buf[8] & 0x7f) << 7 | (buf[9] & 0x7f);
    start = 10 + size + ((buf[5] & 0x10) ? 10 : 0);
  }
  if (end - start > 128 && buf[end - 128] === 0x54 && buf[end - 127] === 0x41 && buf[end - 126] === 0x47) end -= 128;
  while (start < end - 4 && !(buf[start] === 0xff && (buf[start + 1] & 0xe0) === 0xe0)) start++;
  const br = [0,32,40,48,56,64,80,96,112,128,160,192,224,256,320][(buf[start + 2] >> 4) & 0x0f] * 1000;
  const sr = [44100,48000,32000][(buf[start + 2] >> 2) & 0x03];
  const pad = (buf[start + 2] >> 1) & 0x01;
  const flen = br && sr ? Math.floor(144 * br / sr) + pad : 0;
  if (flen) {
    const frame = buf.slice(start, start + flen).toString('latin1');
    if (frame.includes('Xing') || frame.includes('Info') || frame.includes('VBRI')) start += flen;
  }
  return buf.slice(start, end);
}
const items = $input.all();
const voice = [];
const music = {};
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const bin = (items[i].binary && items[i].binary.data) || {};
  const tag = String(j.part || '') + ' ' + String(j.path || j.name || bin.fileName || '');
  const buf = cleanMp3(await this.helpers.getBinaryDataBuffer(i, 'data'));
  if (/^intro\b|factory-intro/.test(tag)) music.intro = buf;
  else if (/^outro\b|factory-outro/.test(tag)) music.outro = buf;
  else if (/^gap\b|factory-gap/.test(tag)) music.gap = buf;
  else voice.push(buf);
}
if (!music.gap) throw new Error('Mix: the silence part is missing');
const withMusic = !!(music.intro && music.outro);
if (voice.length < 2) throw new Error('Mix: expected the hook plus dialogue chunks, got ' + voice.length);
const parts = withMusic ? [voice[0], music.gap, music.intro, ...voice.slice(1), music.gap, music.outro] : [voice[0], music.gap, ...voice.slice(1)];
const merged = Buffer.concat(parts);
const p = $('Plan Release').first().json;
const seconds = Math.round(merged.length * 8 / 128000);
const duration = Math.floor(seconds / 60) + ':' + String(seconds % 60).padStart(2, '0');
const fileName = 'breakpoint-systems-podcast-ep' + String(p.episode_number).padStart(3, '0') + '-' + p.slug.slice(0, 50) + '.mp3';
const binary = await this.helpers.prepareBinaryData(merged, fileName, 'audio/mpeg');
return [{ json: { file_name: fileName, bytes: merged.length, seconds, duration, voice_chunks: voice.length }, binary: { data: binary } }];

// Pair Transistor's upload slot with the mixed MP3
const a = $input.first().json.data.attributes;
return [{ json: { upload_url: a.upload_url, audio_url: a.audio_url, content_type: a.content_type || 'audio/mpeg' }, binary: $('Mix Episode MP3').first().binary }];

// Build the transcript, show notes, Transistor description and (once the Breakpoint site has a Podcast collection) the website item
const S = $('Show Settings').first().json;
const p = $('Plan Release').first().json;
const mix = $('Mix Episode MP3').first().json;
const ep = $('Create Transistor Episode').first().json.data;
const src = $('Build Script Input').first().json;
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const SITE = String(S.website || '').replace(/\/+$/, '');
const pageUrl = SITE + '/podcast/' + p.slug;
const CO = S.cohost_name;
const transcript = p.final_script.split(/\r?\n/).map(l => l.trim()).filter(Boolean).map(l => {
  const m = l.match(/^([^:]{2,30})\s*:\s*(.*)$/);
  if (!m) return '';
  const who = m[1].toLowerCase() === 'billy' ? S.host_name : CO + ' (AI co-host)';
  return '<p><strong>' + esc(who) + ':</strong> ' + esc(m[2].replace(/\[[^\]]{1,30}\]\s*/g, '').trim()) + '</p>';
}).join('');
const bullets = (p.bullets || []).map(b => '<li>' + esc(b) + '</li>').join('');
const guide = !p.source_url ? '' : src.source_type === 'article'
  ? '<p>Source: <a href="' + p.source_url + '" rel="nofollow noopener">' + esc(src.topic) + '</a> (' + esc(src.site) + ')</p>'
  : '<p>Read more: <a href="' + p.source_url + '">' + esc(src.topic) + '</a></p>';
// AI disclosure always lives in the show notes (draft brand rule: AI-voice disclosure required)
const disclosure = '<p>' + esc(S.host_name) + ' is the founder of ' + esc(S.brand_name) + '. Voices in this episode are AI-generated, including Billy\'s, from a script reviewed and approved by Billy Jordan. General information, not advice for your specific business.</p>';
const showNotes = '<p>' + esc(p.summary || p.quick_answer) + '</p>' + (bullets ? '<h3>In this episode</h3><ul>' + bullets + '</ul>' : '') + guide + disclosure;
const booking = '<p>Book an automation audit with Billy and his team: <a href="' + SITE + '">' + SITE.replace(/^https?:\/\//, '') + '</a></p>';
const description = showNotes + booking + (S.webflow_collection_id ? '<p>Episode page and full transcript: <a href="' + pageUrl + '">' + pageUrl + '</a></p>' : '');
const share = (ep.attributes && ep.attributes.share_url) || '';
const embed = share ? share.replace('/s/', '/e/') : '';
const appleLink = /^https:\/\/podcasts\.apple\.com\//.test(String(S.apple_podcasts_url || '')) ? S.apple_podcasts_url : share;
// Field slugs are a starting point: set them to match the Podcast collection when it is created on the Breakpoint site.
const fieldData = {
  name: p.title,
  slug: p.slug,
  'episode-number': p.episode_number,
  'publish-date': p.publish_date_cms,
  duration: (() => { const m = String(mix.duration || '').match(/^(\d+):(\d{1,2})$/); return m ? (+m[1]) + ' min ' + (+m[2]) + ' sec' : String(mix.duration || ''); })(),
  'quick-answer': p.quick_answer,
  'show-notes': showNotes,
  'full-transcript': transcript,
  'transistor-player-url': embed,
  'apple-podcasts-link': appleLink,
  'episode-page-url': pageUrl,
  'seo-title': p.seo_title,
  'meta-description': p.meta_description
};
return [{ json: { fieldData, description, transcript_text: p.final_script.replace(/\[[^\]]{1,30}\]\s*/g, ''), page_url: pageUrl, transistor_episode_id: ep.id, share_url: share, make_web_page: !!S.webflow_collection_id } }];

// Final Slack message and email, with the ElevenLabs monthly usage check
const S = $('Show Settings').first().json;
const p = $('Plan Release').first().json;
const mix = $('Mix Episode MP3').first().json;
